package com.smartretail.supplier.controller;
import com.smartretail.supplier.entity.Supplier; import com.smartretail.supplier.repository.SupplierRepository; import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/suppliers") public class SupplierController { private final SupplierRepository repo; public SupplierController(SupplierRepository repo){this.repo=repo;} record SupplierInput(@NotBlank String name,@NotBlank String phone,@Email String email,String address,String contactPerson,String notes){} private Long business(HttpServletRequest r){return (Long)r.getAttribute("businessId");} private Supplier owned(Long id,Long business){return repo.findByIdAndBusinessId(id,business).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Supplier not found."));} private void apply(Supplier s,SupplierInput i){s.setName(i.name().trim());s.setPhone(i.phone().trim());s.setEmail(blank(i.email()));s.setAddress(blank(i.address()));s.setContactPerson(blank(i.contactPerson()));s.setNotes(blank(i.notes()));} private String blank(String v){return v==null||v.isBlank()?null:v.trim();} @GetMapping public List<Supplier> all(HttpServletRequest r){return repo.findAllByBusinessIdOrderByNameAsc(business(r));} @PostMapping public ResponseEntity<Supplier> create(@jakarta.validation.Valid @RequestBody SupplierInput i,HttpServletRequest r){Long b=business(r);if(repo.existsByBusinessIdAndPhone(b,i.phone().trim()))throw new ResponseStatusException(HttpStatus.CONFLICT,"A supplier with this phone number already exists.");Supplier s=new Supplier();s.setBusinessId(b);apply(s,i);return ResponseEntity.status(201).body(repo.save(s));} @PutMapping("/{id}") public Supplier update(@PathVariable Long id,@jakarta.validation.Valid @RequestBody SupplierInput i,HttpServletRequest r){Long b=business(r);if(repo.existsByBusinessIdAndPhoneAndIdNot(b,i.phone().trim(),id))throw new ResponseStatusException(HttpStatus.CONFLICT,"A supplier with this phone number already exists.");Supplier s=owned(id,b);apply(s,i);return repo.save(s);}@DeleteMapping("/{id}") public Map<String,String> delete(@PathVariable Long id,HttpServletRequest r){repo.delete(owned(id,business(r)));return Map.of("message","Supplier deleted.");}}
